const MS_DAY = 86_400_000;
const end = new Date(Date.now() - (3 * MS_DAY));
const start = new Date(end.getTime() - (27 * MS_DAY));
const isoDate = (date) => date.toISOString().slice(0, 10);
return [{ json: { startDate: isoDate(start), endDate: isoDate(end) } }];

